import subprocess,sys,re,numpy as np
N=[('n05_40',11.5,0.5,40),('n1_40',23,1,40),('n2_40',46,2,40),('n3_40',69,3,40),
   ('n05_100',28.5,0.5,100),('n1_100',57,1,100),('n2_100',114,2,100),('n015_100',8.5,0.15,100),
   ('n1_40b',23,1,40)]
P=[('p05_40',50,0.5,40),('p1_40',100,1,40),('p2_40',200,2,40),('p3_40',300,3,40),
   ('p35_100',175,0.35,100),('p1_100',250,1,100),('p2_100',500,2,100),('p4_100',1000,4,100)]
PARAMS=['id','gm','gds','vdsat','vth','cgs','cgd']
def deck(typ,vds):
    if typ=='n':
        lines=['.lib /opt/sky130/continuous/sky130.lib.spice tt','.include /app/circuit.spi',
          'Vdd vdd 0 1.2','Vng ng 0 0.5','Vnd nd 0 %g'%vds,'Vsn vsn 0 0.30']
        for nm,w,l,it in N:
            if nm.endswith('b'):
                lines.append('X%s nd ng vsn 0 sky130_fd_pr__nfet_01v8_lvt W=%g L=%g nf=1 m=1'%(nm,w,l))
            else:
                lines.append('X%s nd ng 0 0 sky130_fd_pr__nfet_01v8_lvt W=%g L=%g nf=1 m=1'%(nm,w,l))
        lines+=['.dc Vng 0.30 0.90 0.005']
        for nm,w,l,it in N:
            for p in PARAMS:
                lines.append('.print dc @m.x%s.msky130_fd_pr__nfet_01v8_lvt[%s]'%(nm,p))
    else:
        lines=['.lib /opt/sky130/continuous/sky130.lib.spice tt','.include /app/circuit.spi',
          'Vdd vdd 0 1.2','Vpg pg 0 0.7','Vpd pd 0 %g'%(1.2-vds)]
        for nm,w,l,it in P:
            lines.append('X%s pd pg vdd vdd sky130_fd_pr__pfet_01v8_lvt W=%g L=%g nf=1 m=1'%(nm,w,l))
        lines+=['.dc Vpg 0.30 0.90 0.005']
        for nm,w,l,it in P:
            for p in PARAMS:
                lines.append('.print dc @m.x%s.msky130_fd_pr__pfet_01v8_lvt[%s]'%(nm,p))
    lines.append('.end')
    return '\n'.join(lines)+'\n'
def parse(fn,devs):
    txt=open(fn,errors='ignore').read().split('\n')
    # collect blocks: header line contains 'Index', then dashes, then rows
    blocks=[]; i=0
    while i<len(txt):
        if txt[i].lstrip().startswith('Index'):
            hdr=txt[i].split()[1:]
            j=i+2; rows=[]
            while j<len(txt):
                t=txt[j].split('\t')
                t=[x for x in t if x.strip()!='']
                if not t or not re.match(r'^\d+$',t[0].strip()): break
                rows.append([float(x) for x in t[1:]])
                j+=1
            blocks.append((hdr,np.array(rows))); i=j
        else: i+=1
    names=[(nm,p) for nm,w,l,it in devs for p in PARAMS]
    out={k:[] for k in names}
    for hdr,rows in blocks:
        nv=len(hdr)-1
        for c in range(nv):
            pass
    # sequential assignment
    idx=0
    for hdr,rows in blocks:
        nv=len(hdr)-1
        for c in range(nv):
            key=names[idx]; idx+=1
            out[key]=rows[:,1+c]
        out['sweep']=rows[:,0]
    return out
def report(typ,files,targets):
    devs=N if typ=='n' else P
    res={}
    for vds,fn in files:
        d=parse(fn,devs)
        sw=d['sweep']
        for nm,w,l,it in devs:
            idv=np.abs(d[(nm,'id')]); gm=np.abs(d[(nm,'gm')]); gds=np.abs(d[(nm,'gds')])
            vdsat=np.abs(d[(nm,'vdsat')]); vth=d[(nm,'vth')]; cgs=np.abs(d[(nm,'cgs')])
            if typ=='n':
                vgs = sw - (0.30 if nm.endswith('b') else 0.0)
                vdsx = vds-0.30 if nm.endswith('b') else vds
            else:
                vgs = 1.2-sw; vdsx=vds
            k=np.argmin(abs(idv-it*1e-6))
            res[(nm,vds)]=dict(vgs=vgs[k],id=idv[k],gm=gm[k],gds=gds[k],gain=gm[k]/gds[k],
                vdsat=vdsat[k],vth=vth[k] if typ=='n' else -vth[k],cgs=cgs[k],vds=vdsx,
                gmoverid=gm[k]/idv[k])
    # print table
    print("%-9s Vds=%.2f : "%('dev',0),end='')
    ds=[v for v,f in files]
    print("  ".join("Vd=%.2f"%v for v in ds))
    for nm,w,l,it in devs:
        print("%-9s (W=%g L=%g, Itgt=%guA)"%(nm,w,l,it))
        for v in ds:
            r=res[(nm,v)]
            print("   Vd=%.2f  Vgs=%.3f Id=%.1fuA gm=%.3fm gds=%.2fu gm/gds=%5.0f vdsat=%.3f vth=%.3f cgs=%.3ffF gm/Id=%.1f"%(
              v,r['vgs'],r['id']*1e6,r['gm']*1e3,r['gds']*1e6,r['gain'],r['vdsat'],r['vth'],r['cgs']*1e15,r['gmoverid']))
    return res
if __name__=='__main__':
    typ=sys.argv[1]
    files=[]
    for vds in [float(x) for x in sys.argv[2].split(',')]:
        fn='/app/experiments/vch_%s_%g.log'%(typ,vds)
        open('/app/experiments/vch_%s_%g.spice'%(typ,vds),'w').write(deck(typ,vds))
        r=subprocess.run(['ngspice','-b','/app/experiments/vch_%s_%g.spice'%(typ,vds),'-o',fn],capture_output=True,text=True)
        files.append((vds,fn))
    report(typ,files,None)
